const std = @import("std"); const hits = @import("ru-hits-lear.zig"); const trap = @import("pa-trap-dete.zig"); const ocrz = @import("nt-ocrz-exte.zig"); const walk = @import("ru-page-walk.zig"); const inde = @import("st-page-inde.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const builtin = @import("builtin");
const allo = std.testing.allocator;
fn memd() !struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: sqli.Dbzz } { const tmpz = std.testing.tmpDir(.{}); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); return .{ .tmpz = tmpz, .dirz = dirz, .dbzz = try inde.pageOpen(allo, std.testing.io, dirz) }; }
test "replayed results move the winner first; cheaper winner beats a dearer one; unsampled stays in config order" { var dbz2 = try memd(); defer { dbz2.dbzz.close(); allo.free(dbz2.dirz); dbz2.tmpz.cleanup(); } var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const base = [_][]const u8{ "deco", "zenr", "brig" }; const nowz: i64 = 1_000_000_000_000; var ind2: usize = 0; while (ind2 < 3) : (ind2 += 1) { try hits.hitsRecz(&dbz2.dbzz, "a.test", "deco", 2, false, 0, 0, nowz); try hits.hitsRecz(&dbz2.dbzz, "a.test", "zenr", 2, true, 1, 1000, nowz); } const ordz = try hits.hitsOrde(&dbz2.dbzz, aren.allocator(), "a.test", &base, 2, nowz); try std.testing.expectEqualStrings("zenr", ordz[0]); try std.testing.expectEqualStrings("brig", ordz[1]); try std.testing.expectEqualStrings("deco", ordz[2]); ind2 = 0; while (ind2 < 3) : (ind2 += 1) { try hits.hitsRecz(&dbz2.dbzz, "b.test", "deco", 3, true, 2, 3000, nowz); try hits.hitsRecz(&dbz2.dbzz, "b.test", "zenr", 3, true, 5, 9000, nowz); } const ord2 = try hits.hitsOrde(&dbz2.dbzz, aren.allocator(), "b.test", &base, 3, nowz); try std.testing.expectEqualStrings("deco", ord2[0]); try std.testing.expectEqualStrings("zenr", ord2[1]); const fres = try hits.hitsOrde(&dbz2.dbzz, aren.allocator(), "c.test", &base, 2, nowz); try std.testing.expectEqualStrings("deco", fres[0]); }
test "learning resets after 30 days" { var dbz2 = try memd(); defer { dbz2.dbzz.close(); allo.free(dbz2.dirz); dbz2.tmpz.cleanup(); } var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const base = [_][]const u8{ "zenr", "deco" }; const nowz: i64 = 1_000_000_000_000; try hits.hitsRecz(&dbz2.dbzz, "a.test", "zenr", 2, false, 0, 0, nowz); try hits.hitsRecz(&dbz2.dbzz, "a.test", "zenr", 2, false, 0, 0, nowz); const fres = try hits.hitsOrde(&dbz2.dbzz, aren.allocator(), "a.test", &base, 2, nowz); try std.testing.expectEqualStrings("deco", fres[0]); const aged = try hits.hitsOrde(&dbz2.dbzz, aren.allocator(), "a.test", &base, 2, nowz + 31 * 86400000); try std.testing.expectEqualStrings("zenr", aged[0]); }
test "link finder flags every kind of honeypot, keeps real links" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const page = "<a href=\"/real\">ok</a><a href=\"/h1\" style=\"display:none\">x</a><a href=\"/h2\" hidden>x</a><div style=\"opacity:0\"><span><a href=\"/h3\">x</a></span></div><a href=\"/after\">ok2</a><a href=\"/h4\" rel=\"nofollow\">x</a><a href=\"/h5\" class=\"my-honeypot\">x</a><a href=\"/h6\" aria-hidden=\"true\" tabindex=\"-1\">x</a><a href=\"http://other.test/x\">off</a>"; const got2 = try trap.linkFind(aren.allocator(), "http://h.test/p", page); var real: usize = 0; var tra2: usize = 0; for (got2) |lkzz| { if (lkzz.trap) { tra2 += 1; } else { real += 1; } } try std.testing.expectEqual(@as(usize, 2), real); try std.testing.expectEqual(@as(usize, 6), tra2); for (got2) |lkzz| { if (std.mem.eql(u8, lkzz.urlz, "http://h.test/after")) try std.testing.expect(!lkzz.trap); } }
test "walk --follow: honeypot links are never fetched, real link is" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var wlk2 = walk.Walk.init(allo, std.testing.io, .{}, &dbzz, dirz, true); defer wlk2.deinit(); wlk2.gapz = 0; wlk2.base = 0; wlk2.foll = 10; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const hubz = try aren.allocator().dupe(u8, srv2.urlzOfzz(&buf4, "/hub")); _ = try wlk2.walkSeed(&.{hubz}); const sum5 = try wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 2), sum5.done); try std.testing.expectEqual(@as(u32, 4), sum5.trap); for ([_][]const u8{ "/p3", "/p9", "/p8", "/p7" }) |pthz| { var b2z2: [64]u8 = undefined; try std.testing.expect(try inde.pageGetz(&dbzz, aren.allocator(), srv2.urlzOfzz(&b2z2, pthz)) == null); } var b3zz: [64]u8 = undefined; try std.testing.expect(try inde.pageGetz(&dbzz, aren.allocator(), srv2.urlzOfzz(&b3zz, "/p1")) != null); }
test "walk without --follow queues nothing extra" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var wlk2 = walk.Walk.init(allo, std.testing.io, .{}, &dbzz, dirz, true); defer wlk2.deinit(); wlk2.gapz = 0; wlk2.base = 0; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf4: [64]u8 = undefined; const hubz = try aren.allocator().dupe(u8, srv2.urlzOfzz(&buf4, "/hub")); _ = try wlk2.walkSeed(&.{hubz}); const sum5 = try wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 1), sum5.done); try std.testing.expectEqual(@as(u32, 0), sum5.trap); }
test "truncated page and poisoned record are caught" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expect(trap.trunChek("<html><head><title>x</title></head><body><p>cut off mid")); try std.testing.expect(!trap.trunChek("<html><body><p>complete page text</p></body></html>")); const req2 = [_][]const u8{ "name", "price" }; try std.testing.expect((try trap.poisChek(aren.allocator(), "{\"name\":\"Widget\",\"price\":12}", &req2)) == null); try std.testing.expectEqualStrings("price", (try trap.poisChek(aren.allocator(), "{\"name\":\"Widget\",\"price\":null}", &req2)).?); try std.testing.expectEqualStrings("name", (try trap.poisChek(aren.allocator(), "[{\"price\":3}]", &req2)).?); try std.testing.expect((try trap.poisChek(aren.allocator(), "{broken", &req2)) != null); }
test "OCR adapter: off by default, a stand-in tool returns its output, a missing tool is a typed error" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.NoOcr, ocrz.ocrzRunz(aren.allocator(), std.testing.io, "", "x", dirz)); try std.testing.expectError(error.OcrFail, ocrz.ocrzRunz(aren.allocator(), std.testing.io, "/no/such/tool", "x", dirz)); const exe2: []const u8 = if (builtin.os.tag == .windows) "C:\\Windows\\System32\\more.com" else "/bin/cat"; const got2 = ocrz.ocrzRunz(aren.allocator(), std.testing.io, exe2, "scanned words here", dirz) catch return; try std.testing.expectEqualStrings("scanned words here", got2); }
